window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_35", [
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   1. पं. जवाहरलाल नेहरू\nB. 1940 रामगढ़ अधिवेशन   |   2. आचार्य जे.बी. कृपलानी\nC. 1929 लाहौर अधिवेशन   |   3. पं. जवाहरलाल नेहरू (ग्रामीण सत्र)\nD. 1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र)   |   4. मौलाना अबुल कलाम आजाद","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":1,"explanation":"सही सुमेलन: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1940 रामगढ़ अधिवेशन (मौलाना अबुल कलाम आजाद), 1929 लाहौर अधिवेशन (पं. जवाहरलाल नेहरू), 1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र) (पं. जवाहरलाल नेहरू (ग्रामीण सत्र))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. असहयोग आंदोलन को महात्मा गांधी ने 1922 में जलियाँवाला बाग हत्याकांड की भयानक हिंसा के तुरंत बाद वापस ले लिया था।\n2. 1927 में गठित हरकोर्ट बटलर समिति का उद्देश्य भारत में वामपंथी ट्रेड यूनियनों पर प्रतिबंध और नमक कर को दोगुना करना था।\n3. 1920 में स्थापित अखिल भारतीय ट्रेड यूनियन कांग्रेस (AITUC) के प्रथम अध्यक्ष महात्मा गांधी तथा महासचिव लॉर्ड रिपन थे।\n4. एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"'स्वराज मेरा जन्मसिद्ध अधिकार है और मैं इसे लेकर रहूँगा' का ऐतिहासिक उद्घोष किसने किया?","options":["महात्मा गांधी","लाला लाजपत राय","बाल गंगाधर तिलक","सुभाष चंद्र बोस"],"correct":2,"explanation":"तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया। उन्होंने ही 1906 के कलकत्ता व स्वदेशी काल में जनसंघर्ष का मंत्र दिया।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बटलर समिति (1927) : ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध\n2. फ्लाउड आयोग (Floud Commission) : बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा\n3. हंटर शिक्षा आयोग (1882) : पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सर हरकोर्ट बटलर की अध्यक्षता वाली समिति ने कहा कि देसी रियासतें बिना सहमति ब्रिटिश भारतीय उत्तरदायी सरकार को न सौंपी जाएँ।) युग्म 2 सही (सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ।) युग्म 3 गलत (सही: हंटर शिक्षा आयोग (1882) — प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. 1907 सूरत अधिवेशन : सरोजिनी नायडू (प्रथम भारतीय महिला)\n2. 1931 कराची अधिवेशन : सरदार वल्लभभाई पटेल\n3. 1917 कलकत्ता अधिवेशन : डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\n4. 1929 लाहौर अधिवेशन : पं. जवाहरलाल नेहरू","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: '1907 सूरत अधिवेशन' का सही संबंध 'डॉ. रासबिहारी घोष' से है (न कि 'सरोजिनी नायडू (प्रथम भारतीय महिला)' से)। सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड कर्जन (1899-1905)' का ऐतिहासिक संबंध 'प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन' से था।\n2. 27 दिसंबर 1911 को कलकत्ता अधिवेशन में बिशन नारायण धर की अध्यक्षता में पहली बार जन गण मन गाया गया।\n3. 1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)।\n4. 1916 लखनऊ अधिवेशन में ए.सी. मजूमदार की अध्यक्षता में नरम-गरम दल व कांग्रेस-लीग एक मंच पर आए।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'लॉर्ड कर्जन (1899-1905)' का सही संबंध 'बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन' से था — लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।"},
  {"q":"'सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)' के ऐतिहासिक संदर्भ में 'प्रचार व दमन' निम्नलिखित में से क्या है?","options":["1924 बेलगाम (महात्मा गांधी — एकमात्र अध्यक्षता); 1929 लाहौर (जवाहरलाल नेहरू — 'पूर्ण स्वराज' प्रस्ताव, 26 जनवरी 1930 प्रथम स्वतंत्रता दिवस)","1938 हरिपुरा (सुभाष चंद्र बोस — नेहरू की अध्यक्षता में राष्ट्रीय योजना समिति NPC); 1939 त्रिपुरी (बोस ने पट्टाभि सीतारमैय्या को हराया, गांधी मतभेद पर बोस का इस्तीफा, राजेंद्र प्रसाद अध्यक्ष व बोस द्वारा 'फॉरवर्ड ब्लॉक' गठन)","तिलक ने 'मराठा-केसरी' से और बेसेंट ने 'न्यू इंडिया' व 'कॉमनवील' से होमरूल का प्रचार किया; 1917 बेसेंट की गिरफ्तारी पर एस. सुब्रमण्यम अय्यर ने 'नाइटहुड' त्यागा","सेफ्टी वॉल्व सिद्धांत (लाला लाजपत राय ने 'यंग इंडिया' में चर्चा की); आधुनिक मत: 'तड़ित चालक' (Lightning Conductor — गोखले ने ह्यूम का उपयोग किया)"],"correct":2,"explanation":"20 अगस्त 1917 के मोंटेग्यू घोषणा पत्र (ब्रिटिश भारत में क्रमिक उत्तरदायी शासन) के बाद एनी बेसेंट ने अपना होमरूल आंदोलन स्थगित कर दिया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पूना समझौता / पूना पैक्ट (1932 ई.)   |   1. प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\nB. मद्रास की संधि (1769 ई.)   |   2. तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\nC. सुगौली की संधि (1816 ई.)   |   3. दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nD. पेरिस की संधि (1763 ई.)   |   4. आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)","options":["A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: पूना समझौता / पूना पैक्ट (1932 ई.) (दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)), मद्रास की संधि (1769 ई.) (प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)), सुगौली की संधि (1816 ई.) (आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)), पेरिस की संधि (1763 ई.) (तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।\nकथन-2: स्वतंत्रता संग्राम की पुस्तकें के अंतर्गत 'इंडिया विन्स फ्रीडम' का ऐतिहासिक संबंध 'पं. जवाहरलाल नेहरू' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।)। कथन-2 गलत है — 'इंडिया विन्स फ्रीडम' का सही संबंध 'मौलाना अबुल कलाम आजाद' से था — भारत के प्रथम शिक्षा मंत्री मौलाना आजाद ने विभाजन व आजादी के अंतिम वर्षों पर यह संस्मरण लिखा।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारतीय परिषद अधिनियम, 1861 : मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\n2. भारतीय परिषद अधिनियम, 1892 : केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता\n3. चार्टर अधिनियम, 1853 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n4. पिट्स इंडिया एक्ट, 1784 : गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: 1861 के भारतीय परिषद अधिनियम ने कानून निर्माण प्रक्रिया में भारतीय प्रतिनिधियों को शामिल करने की शुरुआत की। (अन्य सही युग्म: भारतीय परिषद अधिनियम, 1892→अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार, चार्टर अधिनियम, 1853→केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता, पिट्स इंडिया एक्ट, 1784→कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 16 अक्टूबर 1905 को बंगाल विभाजन लागू होने पर रवींद्रनाथ टैगोर के आह्वान पर हिंदू-मुसलमानों ने एक-दूसरे को 'राखी' बाँधकर एकता प्रदर्शित की और कृष्ण कुमार मित्र के 'संजीवनी' पत्र ने सर्वप्रथम बहिष्कार का सुझाव दिया।\nकथन-2: सुरेंद्रनाथ बनर्जी व आनंद मोहन बोस द्वारा 1876 में स्थापित 'इंडियन एसोसिएशन ऑफ कलकत्ता' कांग्रेस-पूर्व सबसे महत्वपूर्ण राष्ट्रवादी संगठन था जिसने 1883-85 में अखिल भारतीय राष्ट्रीय सम्मेलन आयोजित किए।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 16 अक्टूबर 1905 को बंगाल विभाजन लागू होने पर रवींद्रनाथ टैगोर के आह्वान पर हिंदू-मुसलमानों ने एक-दूसरे को 'राखी' बाँधकर एकता प्रदर्शित की और कृष्ण कुमार मित्र के 'संजीवनी' पत्र ने सर्वप्रथम बहिष्कार का सुझाव दिया। (2) सुरेंद्रनाथ बनर्जी व आनंद मोहन बोस द्वारा 1876 में स्थापित 'इंडियन एसोसिएशन ऑफ कलकत्ता' कांग्रेस-पूर्व सबसे महत्वपूर्ण राष्ट्रवादी संगठन था जिसने 1883-85 में अखिल भारतीय राष्ट्रीय सम्मेलन आयोजित किए।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1887 मद्रास अधिवेशन   |   1. पं. जवाहरलाल नेहरू\nB. 1929 लाहौर अधिवेशन   |   2. डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\nC. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   3. बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)\nD. 1917 कलकत्ता अधिवेशन   |   4. आचार्य जे.बी. कृपलानी","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: 1887 मद्रास अधिवेशन (बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)), 1929 लाहौर अधिवेशन (पं. जवाहरलाल नेहरू), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1917 कलकत्ता अधिवेशन (डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष))।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1907 सूरत अधिवेशन : डॉ. रासबिहारी घोष\n2. 1885 बंबई अधिवेशन (प्रथम) : आचार्य जे.बी. कृपलानी\n3. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।) युग्म 2 गलत (सही: 1885 बंबई अधिवेशन (प्रथम) — व्योमेश चंद्र बनर्जी)। युग्म 3 गलत (सही: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) — आचार्य जे.बी. कृपलानी)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्लॉड आयोग (1940 ई., बंगाल) : बंगाल में स्थायी बंदोबस्त (जमींदारी प्रथा) की समीक्षा व 'तेभागा' (2/3 हिस्सा किसान को) अनुशंसा\n2. बटलर समिति (1927 ई.) : ब्रिटिश भारत (सर्वोच्च शक्ति) तथा देशी रियासतों के बीच संबंध सुधारना\n3. वुड्स डिस्पैच (1854 ई.) : प्राथमिक स्तर पर देशी भाषा, उच्च स्तर पर अंग्रेजी, महिला शिक्षा व 3 प्रेसीडेंसी विश्वविद्यालय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सर फ्रांसिस फ्लॉड भू-राजस्व आयोग (1940) ने बंगाल की बटाईदार प्रथा व स्थायी बंदोबस्त दोषों को उजागर किया।) युग्म 2 सही (हरकोर्ट बटलर समिति ने कहा कि देशी रियासतों को बिना उनकी सहमति के जिम्मेदार भारतीय सरकार को नहीं सौंपा जाएगा।) युग्म 3 सही (1854 के वुड घोषणापत्र की सिफारिश पर 1857 में कलकत्ता, बंबई व मद्रास विश्वविद्यालय खुले।)।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1911 कलकत्ता अधिवेशन : पं. बिशन नारायण धर\n2. 1885 बंबई अधिवेशन (प्रथम) : व्योमेश चंद्र बनर्जी\n3. 1896 कलकत्ता अधिवेशन : रहीमतुल्ला एम. सयानी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (27 दिसंबर 1911 को कलकत्ता अधिवेशन में बिशन नारायण धर की अध्यक्षता में पहली बार जन गण मन गाया गया।) युग्म 2 सही (28 दिसंबर 1885 को बंबई में हुए पहले कांग्रेस अधिवेशन की अध्यक्षता डब्ल्यू.सी. बनर्जी ने की।) युग्म 3 सही (1896 कलकत्ता अधिवेशन में रवींद्रनाथ टैगोर ने बंकिम चंद्र का 'वंदे मातरम' गाया; अध्यक्ष सयानी थे।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।\nकथन-2: क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'केंद्रीय असेंबली बम कांड (1929)' का ऐतिहासिक संबंध 'बीना दास' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।)। कथन-2 गलत है — 'केंद्रीय असेंबली बम कांड (1929)' का सही संबंध 'भगत सिंह एवं बटुकेश्वर दत्त' से था — उनका उद्देश्य किसी की हत्या नहीं बल्कि 'बहरों को सुनाने' व ट्रेड डिस्प्यूट्स/पब्लिक सेफ्टी बिल का विरोध करना था।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n2. करो या मरो (Do or Die) : राम प्रसाद बिस्मिल (काकोरी कांड)\n3. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : स्वामी दयानंद सरस्वती\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (बाल गंगाधर तिलक ने 1916 के लखनऊ कांग्रेस अधिवेशन और होमरूल अभियान में यह उद्घोष किया।) युग्म 2 गलत (सही: करो या मरो (Do or Die) — महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942))। युग्म 3 गलत (सही: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) — राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. उनका उद्देश्य किसी की हत्या नहीं बल्कि 'बहरों को सुनाने' व ट्रेड डिस्प्यूट्स/पब्लिक सेफ्टी बिल का विरोध करना था।\n2. भारत के प्रथम शिक्षा मंत्री मौलाना आजाद ने विभाजन व आजादी के अंतिम वर्षों पर यह संस्मरण लिखा।\n3. 1916 ई. में एनी बेसेंट ने अपनी होमरूल लीग की शुरुआत बाल गंगाधर तिलक से पहले पुणे से की थी और इसमें 'जवाहरलाल नेहरू' शामिल नहीं हुए।\n4. एंड्रयू फ्रेजर की अध्यक्षता वाले आयोग की सिफारिश पर सभी प्रांतों में पुलिस व गुप्तचर (CID) विभाग बने।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अप्रैल 1916 में पहले तिलक ने अपनी इंडियन होमरूल लीग स्थापित की, तत्पश्चात सितंबर 1916 में एनी बेसेंट ने मद्रास (अडयार) से प्रारंभ की, जिससे नेहरू व मोतीलाल नेहरू भी जुड़े।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1907 सूरत अधिवेशन' का ऐतिहासिक संबंध 'पं. बिशन नारायण धर' से था।\n2. 1916 लखनऊ अधिवेशन में ए.सी. मजूमदार की अध्यक्षता में नरम-गरम दल व कांग्रेस-लीग एक मंच पर आए।\n3. 1935 के भारत शासन अधिनियम ने बर्मा को भारत से अलग (1937 में प्रभावी) किया, सिंध और उड़ीसा दो नए प्रांत बनाए, तथा मताधिकार लगभग 10% (लगभग 14% ब्रिटिश भारत जनसंख्या) तक बढ़ाया।\n4. लॉर्ड कैनिंग कंपनी के अंतिम गवर्नर-जनरल तथा 1858 के बाद भारत के प्रथम वायसराय बने।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: '1907 सूरत अधिवेशन' का सही संबंध 'डॉ. रासबिहारी घोष' से था — सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : स्वामी दयानंद सरस्वती\n2. ब्रिटिश साम्राज्य के ताबूत में कील : लाला लाजपत राय (साइमन कमीशन विरोध)\n3. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\n4. स्वराज मेरा जन्मसिद्ध अधिकार है : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: लाहौर में 30 अक्टूबर 1928 को साइमन विरोधी जुलूस में पुलिस लाठीचार्ज में घायल लाला लाजपत राय ने यह कथन कहा। (अन्य सही युग्म: सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)→राम प्रसाद बिस्मिल (काकोरी कांड), वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग→स्वामी दयानंद सरस्वती, स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))।"},
  {"q":"ऐतिहासिक संदर्भ में 'सूरत (1907 — अध्यक्ष रासबिहारी घोष, नरम व गरम दल में विभाजन); मुस्लिम लीग (30 दिसंबर 1906 ढाका — आगा खाँ, सलीमुल्लाह व मोहसिन-उल-मुल्क); होमरूल लीग (अप्रैल 1916 तिलक — बेलगाम/पुणे; सितंबर 1916 एनी बेसेंट — अडयार, मद्रास)' (प्रमुख राजनीतिक घटनाएँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","प्रमुख ऐतिहासिक कांग्रेस अधिवेशन (1896–1929)","1937 के प्रांतीय चुनाव, 28 माह के मंत्रिमंडल व कांग्रेस संकट (1938-39)","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)"],"correct":3,"explanation":"20 अगस्त 1917 के मोंटेग्यू घोषणा पत्र (ब्रिटिश भारत में क्रमिक उत्तरदायी शासन) के बाद एनी बेसेंट ने अपना होमरूल आंदोलन स्थगित कर दिया।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती\n3. ब्रिटिश साम्राज्य के ताबूत में कील : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की।) युग्म 2 सही (स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की।) युग्म 3 गलत (सही: ब्रिटिश साम्राज्य के ताबूत में कील — लाला लाजपत राय (साइमन कमीशन विरोध))।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'स्वराज मेरा जन्मसिद्ध अधिकार है' का ऐतिहासिक संबंध 'लाला लाजपत राय' से था।\nकथन-2: आजाद हिंद फौज (INA) की पहली सैन्य स्थापना 1943 में बर्लिन में रासबिहारी बोस की बजाय सरदार भगत सिंह के नेतृत्व में हुई थी।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'स्वराज मेरा जन्मसिद्ध अधिकार है' का सही संबंध 'बाल गंगाधर तिलक' से था — तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया। (2) आजाद हिंद फौज (INA) की प्रथम स्थापना का विचार व गठन 1942 में दक्षिण-पूर्व एशिया (मलय) में कैप्टन मोहन सिंह व जापानी मेजर फुजिवारा की सहायता से हुआ, जिसे 1943 में रासबिहारी बोस ने सुभाष को सौंपा।"},
  {"q":"[UPSC Prelims पैटर्न — क्रांतिकारी घटनाएँ एवं नायक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बंगाल गवर्नर पर गोली (1932) : बीना दास\n2. दिल्ली षड्यंत्र केस (1912) : मदनलाल धींगरा\n3. कर्जन वायली वध (लंदन, 1909) : सरदार उधम सिंह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (युगांतर व क्रांतिकारी छात्रा समूह से जुड़ी बीना दास ने भरी सभा में गवर्नर पर गोली चलाई।) युग्म 2 गलत (सही: दिल्ली षड्यंत्र केस (1912) — रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास))। युग्म 3 गलत (सही: कर्जन वायली वध (लंदन, 1909) — मदनलाल धींगरा)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।\nकथन-2: स्वतंत्रता संग्राम की पुस्तकें के अंतर्गत 'अनहैप्पी इंडिया (1928)' का ऐतिहासिक संबंध 'नेताजी सुभाष चंद्र बोस' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।)। कथन-2 गलत है — 'अनहैप्पी इंडिया (1928)' का सही संबंध 'लाला लाजपत राय' से था — लाला लाजपत राय ने 1928 में 'अनहैप्पी इंडिया' द्वारा ब्रिटिश औपनिवेशिक शासन व आर्थिक शोषण की पोल खोली।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारत शासन अधिनियम, 1935   |   1. मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\nB. पिट्स इंडिया एक्ट, 1784   |   2. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nC. चार्टर अधिनियम, 1833   |   3. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\nD. भारतीय परिषद अधिनियम, 1909   |   4. कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण","options":["A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1"],"correct":1,"explanation":"सही सुमेलन: भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण), पिट्स इंडिया एक्ट, 1784 (कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)), भारतीय परिषद अधिनियम, 1909 (मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य)।"},
  {"q":"[UPSC Prelims पैटर्न — स्वतंत्रता संग्राम की पुस्तकें] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अनहैप्पी इंडिया (1928) : विनायक दामोदर सावरकर\n2. द इंडियन वार ऑफ इंडिपेंडेंस 1857 : नेताजी सुभाष चंद्र बोस\n3. द इंडियन स्ट्रगल : महात्मा गांधी (लंदन से दक्षिण अफ्रीका जहाज पर)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: अनहैप्पी इंडिया (1928) — लाला लाजपत राय)। युग्म 2 गलत (सही: द इंडियन वार ऑफ इंडिपेंडेंस 1857 — विनायक दामोदर सावरकर)। युग्म 3 गलत (सही: द इंडियन स्ट्रगल — नेताजी सुभाष चंद्र बोस)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: स्वदेशी आंदोलन के दौरान भारतीय राष्ट्रीय कांग्रेस ने 1907 में पूर्णतः क्रांतिकारी सशस्त्र हिंसा को आधिकारिक नीति के रूप में अपना लिया।\nकथन-2: 1928 की नेहरू रिपोर्ट ने भारत के लिए डोमिनियन स्टेटस को अस्वीकार कर तत्काल 'पूर्ण स्वतंत्र समाजवादी गणराज्य' और पृथक सांप्रदायिक निर्वाचक मंडल की सिफारिश की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) स्वदेशी आंदोलन में जनसंपर्क (अश्विनी कुमार दत्त की स्वदेश बांधव समिति आदि) के साथ-साथ रचनात्मक आत्मनिर्भरता पर बल था, पर 1907 में तरीकों के मतभेद पर सूरत में कांग्रेस विभाजित हो गई। (2) 1928 की नेहरू रिपोर्ट ने 'डोमिनियन स्टेटस' (औपनिवेशिक स्वराज्य) और पृथक निर्वाचक मंडल को समाप्त कर आरक्षित सीटों के साथ 'संयुक्त निर्वाचक मंडल' की अनुशंसा की थी; इस पर युवा जवाहरलाल व सुभाष ने 'इंडिपेंडेंस फॉर इंडिया लीग' बनाई।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'स्वराज मेरा जन्मसिद्ध अधिकार है' का ऐतिहासिक संबंध 'लाला लाजपत राय' से था।\n2. 28 दिसंबर 1885 को बंबई में हुए पहले कांग्रेस अधिवेशन की अध्यक्षता डब्ल्यू.सी. बनर्जी ने की।\n3. लाला लाजपत राय ने 1928 में 'अनहैप्पी इंडिया' द्वारा ब्रिटिश औपनिवेशिक शासन व आर्थिक शोषण की पोल खोली।\n4. भारत छोड़ो आंदोलन के दौरान अहमदनगर फोर्ट जेल में नेहरूजी ने भारतीय सभ्यता-इतिहास पर यह कालजयी कृति लिखी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'स्वराज मेरा जन्मसिद्ध अधिकार है' का सही संबंध 'बाल गंगाधर तिलक' से था — तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1887 मद्रास अधिवेशन' का ऐतिहासिक संबंध 'जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)' से था।\n2. 1942 के भारत छोड़ो आंदोलन के दौरान सबसे अल्पकालिक समानांतर सरकार सतारा में केवल एक सप्ताह चली जबकि सबसे दीर्घकालिक बलिया में तीन वर्षों तक चली।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1888 इलाहाबाद अधिवेशन' का ऐतिहासिक संबंध 'रहीमतुल्ला एम. सयानी' से था।\n4. तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1929 लाहौर अधिवेशन   B. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा\nC. बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन   D. 1907 सूरत अधिवेशन\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा","बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन","1929 लाहौर अधिवेशन","1907 सूरत अधिवेशन"],"correct":1,"explanation":"बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन (1905 ई.), 1907 सूरत अधिवेशन (1907 ई.), 1929 लाहौर अधिवेशन (1929 ई.), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (1944 ई.)। अतः सर्वप्रथम बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   1. डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\nB. 1907 सूरत अधिवेशन   |   2. सरदार वल्लभभाई पटेल\nC. 1931 कराची अधिवेशन   |   3. आचार्य जे.बी. कृपलानी\nD. 1917 कलकत्ता अधिवेशन   |   4. डॉ. रासबिहारी घोष","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":2,"explanation":"सही सुमेलन: 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1907 सूरत अधिवेशन (डॉ. रासबिहारी घोष), 1931 कराची अधिवेशन (सरदार वल्लभभाई पटेल), 1917 कलकत्ता अधिवेशन (डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष))।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. आराम हराम है / Who lives if India dies : रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)\n2. सरफरोशी की तमन्ना... : सुभाष चंद्र बोस\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक\n4. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा : लाला लाजपत राय","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया। (अन्य सही युग्म: आराम हराम है / Who lives if India dies→जवाहरलाल नेहरू, सरफरोशी की तमन्ना...→रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी), तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा→सुभाष चंद्र बोस)।"},
  {"q":"1907 के ऐतिहासिक सूरत कांग्रेस अधिवेशन (जिसमें कांग्रेस विभाजित हुई) के अध्यक्ष कौन थे?","options":["बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","डॉ. रासबिहारी घोष","जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)","व्योमेश चंद्र बनर्जी"],"correct":1,"explanation":"सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए। तिलक चाहते थे कि लाला लाजपत राय या तिलक के प्रस्ताव स्वीकार हों।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'हंटर समिति (डिसऑर्डर्स इन्क्वायरी, 1919)' का ऐतिहासिक संबंध 'भारतीय औद्योगिक श्रम (मजदूरों) की कार्यदशा व कल्याण स्थिति की जांच' से था।\n2. लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।\n3. ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'करो या मरो (Do or Die)' का ऐतिहासिक संबंध 'राम प्रसाद बिस्मिल (काकोरी कांड)' से था।\n4. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1896 कलकत्ता अधिवेशन' का ऐतिहासिक संबंध 'डॉ. रासबिहारी घोष' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1907 सूरत अधिवेशन : डॉ. रासबिहारी घोष\n2. 1911 कलकत्ता अधिवेशन : पं. बिशन नारायण धर\n3. 1916 लखनऊ अधिवेशन : महात्मा गांधी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।) युग्म 2 सही (27 दिसंबर 1911 को कलकत्ता अधिवेशन में बिशन नारायण धर की अध्यक्षता में पहली बार जन गण मन गाया गया।) युग्म 3 गलत (सही: 1916 लखनऊ अधिवेशन — अंबिका चरण मजूमदार)।"},
  {"q":"1917 के कलकत्ता कांग्रेस अधिवेशन की अध्यक्षता करने वाली प्रथम महिला कौन थीं?","options":["जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)","व्योमेश चंद्र बनर्जी","बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)"],"correct":3,"explanation":"एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं। होमरूल आंदोलन में गिरफ्तारी व रिहाई के बाद उन्हें यह सम्मान मिला।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. फ्लाउड आयोग (Floud Commission)   B. लॉर्ड कर्जन (1899-1905)\nC. गांधी-अंबेडकर वैचारिक बहस एवं दलित आंदोलन के प्रमुख संगठन   D. द इंडियन वार ऑफ इंडिपेंडेंस 1857\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["द इंडियन वार ऑफ इंडिपेंडेंस 1857","गांधी-अंबेडकर वैचारिक बहस एवं दलित आंदोलन के प्रमुख संगठन","लॉर्ड कर्जन (1899-1905)","फ्लाउड आयोग (Floud Commission)"],"correct":2,"explanation":"लॉर्ड कर्जन (1899-1905) (1905 ई.), द इंडियन वार ऑफ इंडिपेंडेंस 1857 (1909 ई.), गांधी-अंबेडकर वैचारिक बहस एवं दलित आंदोलन के प्रमुख संगठन (1927 ई.), फ्लाउड आयोग (Floud Commission) (1940 ई.)। अतः सर्वप्रथम लॉर्ड कर्जन (1899-1905)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ली आयोग (Lee Commission, 1923) : अखिल भारतीय सिविल सेवा में भारतीय व ब्रिटिश 50-50 अनुपात\n2. ह्विटले आयोग (Whitley, 1929) : औद्योगिक श्रमिकों एवं बागान मजदूरों की दशा व वेतन\n3. बटलर समिति (1927) : प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड ली की अध्यक्षता में आयोग ने 15 वर्षों में ICS में 50% भारतीय करने व लोक सेवा आयोग (1926) बनाने की सिफारिश की।) युग्म 2 सही (जे.एच. ह्विटले की अध्यक्षता में 1929 में श्रम दशाओं पर आयोग बना; इसी तरह 1926 में कृषि हेतु 'लिनलिथगो आयोग' आया।) युग्म 3 गलत (सही: बटलर समिति (1927) — ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. स्वराज मेरा जन्मसिद्ध अधिकार है   |   1. महात्मा गांधी\nB. विजयी विश्व तिरंगा प्यारा   |   2. बाल गंगाधर तिलक\nC. करो या मरो (Do or Die)   |   3. लाला लाजपत राय\nD. मेरे शरीर पर पड़ी एक-एक लाठी...   |   4. श्यामलाल गुप्त 'पार्षद'","options":["A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: स्वराज मेरा जन्मसिद्ध अधिकार है (बाल गंगाधर तिलक), विजयी विश्व तिरंगा प्यारा (श्यामलाल गुप्त 'पार्षद'), करो या मरो (Do or Die) (महात्मा गांधी), मेरे शरीर पर पड़ी एक-एक लाठी... (लाला लाजपत राय)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग' का ऐतिहासिक संबंध 'पं. जवाहरलाल नेहरू' से था।\n2. जून 1945 के शिमला सम्मेलन की अध्यक्षता सुभाष चंद्र बोस ने की थी और इसमें पाकिस्तान के गठन पर अंतिम हस्ताक्षर हो गए थे।\n3. संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'भारतीय परिषद अधिनियम, 1861' का ऐतिहासिक संबंध 'अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार' से था।\n4. सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"नरम दल बनाम गरम दल की विचारधारा एवं कार्यप्रणाली — इसके संबंध में 'मुख्य अंतर' कौन/क्या था?","options":["बंगभाषा प्रकाशिका सभा (1836), लैंडहोल्डर्स सोसाइटी (1838 द्वारकानाथ टैगोर — प्रथम राजनीतिक संगठन), ईस्ट इंडिया एसोसिएशन (1866 लंदन, दादाभाई नौरोजी), पूना सार्वजनिक सभा (1870 एम.जी. रानाडे व जी.वी. जोशी), इंडियन एसोसिएशन (1876 सुरेंद्रनाथ बनर्जी व आनंद मोहन बोस)","28 दिसंबर 1885 गोकुलदास तेजपाल संस्कृत कॉलेज, बंबई (72 प्रतिनिधि, ए.ओ. ह्यूम द्वारा पहल, वायसराय डफरिन); 1885 बंबई (व्योमेश चंद्र बनर्जी); 1886 कलकत्ता (दादाभाई नौरोजी); 1887 मद्रास (बदरुद्दीन तैयबजी — प्रथम मुस्लिम अध्यक्ष); 1888 इलाहाबाद (जॉर्ज यूल — प्रथम अंग्रेज अध्यक्ष)","नरम दल (1885-1905: दादाभाई, गोखले, मेहता, सुरेंद्रनाथ — संवैधानिक 3P: प्रार्थना, याचिका, विरोध; शहरी अभिजात्य आधार, ब्रिटिश न्याय में आस्था); गरम दल (1905-1918: लाल-बाल-पाल व अरबिंदो — निष्क्रिय प्रतिरोध, बहिष्कार, राष्ट्रीय शिक्षा, जन-आंदोलन व पूर्ण स्वराज लक्ष्य)","घोषणा: 19/20 जुलाई 1905; टाउन हॉल बैठक: 7 अगस्त 1905 (बहिष्कार प्रस्ताव); प्रभावी: 16 अक्टूबर 1905 ('शोक दिवस', राखी दिवस व अरंधन); तिलक (बंबई-पुणे), लाजपत राय व अजीत सिंह (पंजाब), चिदंबरम पिल्लै (मद्रास), सैय्यद हैदर रजा (दिल्ली)"],"correct":2,"explanation":"यद्यपि उदारवादियों को तात्कालिक सुधार कम मिले, किंतु उन्होंने दादाभाई नौरोजी व आर.सी. दत्त के नेतृत्व में ब्रिटिश साम्राज्यवाद की आर्थिक लूट को बेनकाब कर राष्ट्रवादी आधार तैयार किया।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1907 सूरत अधिवेशन : डॉ. रासबिहारी घोष\n2. 1887 मद्रास अधिवेशन : बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)\n3. 1924 बेलगाम अधिवेशन : महात्मा गांधी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।) युग्म 2 सही (1887 मद्रास अधिवेशन में बदरुद्दीन तैयबजी ने कांग्रेस के धर्मनिरपेक्ष स्वरूप को सुदृढ़ किया।) युग्म 3 सही (कर्नाटक के बेलगाम में 1924 में महात्मा गांधी ने जीवन में केवल एक बार कांग्रेस अध्यक्षता की।)।"},
  {"q":"[UPSC Prelims PYQ] भारतीय स्वतंत्रता आंदोलन के संदर्भ में, 'स्वदेशी और बहिष्कार' को पहली बार किस घटना के दौरान संघर्ष की विधि के रूप में अपनाया गया था?","options":["बंगाल विभाजन के विरुद्ध आंदोलन (1905)","होमरूल आंदोलन (1916)","साइमन कमीशन का भारत आगमन (1928)","असहयोग आंदोलन (1920)"],"correct":0,"explanation":"लॉर्ड कर्जन के बंगाल विभाजन (1905) के विरोध में 7 अगस्त 1905 को कलकत्ता टाउन हॉल से पहली बार अखिल भारतीय स्तर पर स्वदेशी और बहिष्कार को संघर्ष पद्धति बनाया गया (UPSC CSE 2016)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. क्रिप्स मिशन (1942) में प्रांतों को भारतीय संघ से अलग रहकर अपना पृथक संविधान बनाने का अधिकार दिया गया था, जिसे कांग्रेस ने भारत के संभावित बाल्कनीकरण के रूप में अस्वीकार किया।\n2. 1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई।\n3. स्वदेशी आंदोलन के दौरान भारतीय राष्ट्रीय कांग्रेस ने 1907 में पूर्णतः क्रांतिकारी सशस्त्र हिंसा को आधिकारिक नीति के रूप में अपना लिया।\n4. इंडिया हाउस से जुड़े मदनलाल धींगरा ने 1 जुलाई 1909 को लंदन में कर्जन वायली को गोली मारी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: स्वदेशी आंदोलन में जनसंपर्क (अश्विनी कुमार दत्त की स्वदेश बांधव समिति आदि) के साथ-साथ रचनात्मक आत्मनिर्भरता पर बल था, पर 1907 में तरीकों के मतभेद पर सूरत में कांग्रेस विभाजित हो गई।"},
  {"q":"[PSC/CDS युग्म पहचान — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. 1940 रामगढ़ अधिवेशन : आचार्य जे.बी. कृपलानी\n2. 1917 कलकत्ता अधिवेशन : डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\n3. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) : डॉ. रासबिहारी घोष\n4. 1907 सूरत अधिवेशन : जॉर्ज यूल (प्रथम अंग्रेज अध्यक्ष)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं। (अन्य सही युग्म: 1940 रामगढ़ अधिवेशन→मौलाना अबुल कलाम आजाद, 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)→आचार्य जे.बी. कृपलानी, 1907 सूरत अधिवेशन→डॉ. रासबिहारी घोष)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n3. लॉर्ड मेयो (1869-72) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 2 सही (वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।) युग्म 3 गलत (सही: लॉर्ड मेयो (1869-72) — 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण)।"},
  {"q":"ऐतिहासिक संदर्भ में 'नरम दल (1885-1905: दादाभाई, गोखले, मेहता, सुरेंद्रनाथ — संवैधानिक 3P: प्रार्थना, याचिका, विरोध; शहरी अभिजात्य आधार, ब्रिटिश न्याय में आस्था); गरम दल (1905-1918: लाल-बाल-पाल व अरबिंदो — निष्क्रिय प्रतिरोध, बहिष्कार, राष्ट्रीय शिक्षा, जन-आंदोलन व पूर्ण स्वराज लक्ष्य)' (मुख्य अंतर) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन","कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","नरम दल बनाम गरम दल की विचारधारा एवं कार्यप्रणाली"],"correct":3,"explanation":"यद्यपि उदारवादियों को तात्कालिक सुधार कम मिले, किंतु उन्होंने दादाभाई नौरोजी व आर.सी. दत्त के नेतृत्व में ब्रिटिश साम्राज्यवाद की आर्थिक लूट को बेनकाब कर राष्ट्रवादी आधार तैयार किया।"},
  {"q":"[PSC/CDS युग्म पहचान — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. भारतीय परिषद अधिनियम, 1909 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\n2. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\n3. चार्टर अधिनियम, 1813 : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n4. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":1,"explanation":"केवल युग्म 2 सही है: 1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई। (अन्य सही युग्म: भारतीय परिषद अधिनियम, 1909→मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य, चार्टर अधिनियम, 1813→भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष, भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)→प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी।\n2. जे.एच. ह्विटले की अध्यक्षता में 1929 में श्रम दशाओं पर आयोग बना; इसी तरह 1926 में कृषि हेतु 'लिनलिथगो आयोग' आया।\n3. उदारवादी (नरमपंथी) नेताओं ने भारत की सभी ग्राम पंचायतों में सशस्त्र कर-बंदी व ब्रिटिश वस्तुओं के पूर्ण बहिष्कार को अपनी मुख्य रणनीति बनाया था।\n4. गांव में होने वाले पहले कांग्रेस अधिवेशन (फैजपुर) में 13 सूत्री कृषि कार्यक्रम घोषित हुआ।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: उदारवादियों ने संवैधानिक सुधार, विधानमंडलों में प्रतिनिधित्व व जनमत निर्माण ('प्रार्थना-याचिका') पर बल दिया, जबकि बहिष्कार व जन-संघर्ष को गरमपंथियों ने अपनाया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1907 सूरत अधिवेशन   B. हिंद स्वराज (1909, गुजराती)\nC. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   D. 1937 के प्रांतीय चुनाव, 28 माह के मंत्रिमंडल व कांग्रेस संकट (1938-39)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["1907 सूरत अधिवेशन","हिंद स्वराज (1909, गुजराती)","सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)","1937 के प्रांतीय चुनाव, 28 माह के मंत्रिमंडल व कांग्रेस संकट (1938-39)"],"correct":0,"explanation":"1907 सूरत अधिवेशन (1907 ई.), हिंद स्वराज (1909, गुजराती) (1909 ई.), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (1927 ई.), 1937 के प्रांतीय चुनाव, 28 माह के मंत्रिमंडल व कांग्रेस संकट (1938-39) (1939 ई.)। अतः सर्वप्रथम 1907 सूरत अधिवेशन।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n2. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n3. लॉर्ड विलियम बेंटिंक (1828-35) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।) युग्म 2 सही (अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी।) युग्म 3 गलत (सही: लॉर्ड विलियम बेंटिंक (1828-35) — सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. ब्रिटिश साम्राज्य के ताबूत में कील   |   1. नेताजी सुभाष चंद्र बोस\nB. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   |   2. राम प्रसाद बिस्मिल (काकोरी कांड)\nC. आराम हराम है / 'Who lives if India dies?'   |   3. लाला लाजपत राय (साइमन कमीशन विरोध)\nD. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   |   4. पं. जवाहरलाल नेहरू","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: ब्रिटिश साम्राज्य के ताबूत में कील (लाला लाजपत राय (साइमन कमीशन विरोध)), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (नेताजी सुभाष चंद्र बोस), आराम हराम है / 'Who lives if India dies?' (पं. जवाहरलाल नेहरू), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करो या मरो (Do or Die)   |   1. जवाहरलाल नेहरू\nB. आराम हराम है / Who lives if India dies   |   2. लाला लाजपत राय\nC. सरफरोशी की तमन्ना...   |   3. महात्मा गांधी\nD. मेरे शरीर पर पड़ी एक-एक लाठी...   |   4. रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":0,"explanation":"सही सुमेलन: करो या मरो (Do or Die) (महात्मा गांधी), आराम हराम है / Who lives if India dies (जवाहरलाल नेहरू), सरफरोशी की तमन्ना... (रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)), मेरे शरीर पर पड़ी एक-एक लाठी... (लाला लाजपत राय)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — क्रांतिकारी घटनाएँ एवं नायक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. दिल्ली षड्यंत्र केस (1912)   |   1. खुदीराम बोस एवं प्रफुल्ल चाकी\nB. काकोरी कांड (9 अगस्त 1925)   |   2. मदनलाल धींगरा\nC. कर्जन वायली वध (लंदन, 1909)   |   3. रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)\nD. मुजफ्फरपुर बम कांड (1908)   |   4. HRA (रामप्रसाद बिस्मिल, अशफाकुल्ला, रोशन, राजेंद्र लाहिड़ी)","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"correct":2,"explanation":"सही सुमेलन: दिल्ली षड्यंत्र केस (1912) (रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)), काकोरी कांड (9 अगस्त 1925) (HRA (रामप्रसाद बिस्मिल, अशफाकुल्ला, रोशन, राजेंद्र लाहिड़ी)), कर्जन वायली वध (लंदन, 1909) (मदनलाल धींगरा), मुजफ्फरपुर बम कांड (1908) (खुदीराम बोस एवं प्रफुल्ल चाकी)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. भीमराव अंबेडकर तीनों गोलमेज सम्मेलनों (1930, 1931, 1932) में शामिल हुए थे, जबकि कांग्रेस ने केवल द्वितीय गोलमेज सम्मेलन (1931) में गांधीजी के नेतृत्व में भाग लिया।\n2. 1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1917 कलकत्ता अधिवेशन' का ऐतिहासिक संबंध 'महात्मा गांधी' से था।\n4. सरकारी खजाना लूटकर हथियार खरीदने हेतु HRA ने 8 डाउन ट्रेन रोकी; चार नायकों को फांसी हुई।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: '1917 कलकत्ता अधिवेशन' का सही संबंध 'डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)' से था — एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।\nकथन-2: उनका उद्देश्य किसी की हत्या नहीं बल्कि 'बहरों को सुनाने' व ट्रेड डिस्प्यूट्स/पब्लिक सेफ्टी बिल का विरोध करना था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)। (2) उनका उद्देश्य किसी की हत्या नहीं बल्कि 'बहरों को सुनाने' व ट्रेड डिस्प्यूट्स/पब्लिक सेफ्टी बिल का विरोध करना था।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. माइकल ओ डायर वध (1940)   B. पूना समझौता / पूना पैक्ट (1932 ई.)\nC. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)   D. आराम हराम है / 'Who lives if India dies?'\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["पूना समझौता / पूना पैक्ट (1932 ई.)","आराम हराम है / 'Who lives if India dies?'","माइकल ओ डायर वध (1940)","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)"],"correct":3,"explanation":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), आराम हराम है / 'Who lives if India dies?' (1929 ई.), पूना समझौता / पूना पैक्ट (1932 ई.) (1932 ई.), माइकल ओ डायर वध (1940) (1940 ई.)। अतः सर्वप्रथम सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — स्वतंत्रता संग्राम की पुस्तकें] सूची-I को सूची-II से सुमेलित कीजिए:\nA. द डिस्कवरी ऑफ इंडिया   |   1. लाला लाजपत राय\nB. अनहैप्पी इंडिया (1928)   |   2. महात्मा गांधी (लंदन से दक्षिण अफ्रीका जहाज पर)\nC. द इंडियन वार ऑफ इंडिपेंडेंस 1857   |   3. पं. जवाहरलाल नेहरू\nD. हिंद स्वराज (1909, गुजराती)   |   4. विनायक दामोदर सावरकर","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":0,"explanation":"सही सुमेलन: द डिस्कवरी ऑफ इंडिया (पं. जवाहरलाल नेहरू), अनहैप्पी इंडिया (1928) (लाला लाजपत राय), द इंडियन वार ऑफ इंडिपेंडेंस 1857 (विनायक दामोदर सावरकर), हिंद स्वराज (1909, गुजराती) (महात्मा गांधी (लंदन से दक्षिण अफ्रीका जहाज पर))।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. स्वराज मेरा जन्मसिद्ध अधिकार है : श्यामलाल गुप्त 'पार्षद'\n2. विजयी विश्व तिरंगा प्यारा : जवाहरलाल नेहरू\n3. आराम हराम है / Who lives if India dies : भगत सिंह (रचयिता: हसरत मोहानी)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: स्वराज मेरा जन्मसिद्ध अधिकार है — बाल गंगाधर तिलक)। युग्म 2 गलत (सही: विजयी विश्व तिरंगा प्यारा — श्यामलाल गुप्त 'पार्षद')। युग्म 3 गलत (सही: आराम हराम है / Who lives if India dies — जवाहरलाल नेहरू)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)   B. स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)\nC. द डिस्कवरी ऑफ इंडिया   D. ब्रिटिश साम्राज्य के ताबूत में कील\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","द डिस्कवरी ऑफ इंडिया","ब्रिटिश साम्राज्य के ताबूत में कील"],"correct":1,"explanation":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928) (1923 ई.), ब्रिटिश साम्राज्य के ताबूत में कील (1928 ई.), द डिस्कवरी ऑफ इंडिया (1946 ई.)। अतः सर्वप्रथम सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1907 सूरत अधिवेशन' का ऐतिहासिक संबंध 'पं. बिशन नारायण धर' से था।\nकथन-2: 1946 की अंतरिम सरकार में मुस्लिम लीग के सदस्य लियाकत अली खाँ को रक्षा मंत्रालय तथा बलदेव सिंह को वित्त मंत्रालय सौंपा गया था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) '1907 सूरत अधिवेशन' का सही संबंध 'डॉ. रासबिहारी घोष' से था — सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए। (2) 1946 की अंतरिम सरकार में लियाकत अली खाँ (मुस्लिम लीग) को 'वित्त मंत्रालय' तथा सरदार बलदेव सिंह को 'रक्षा मंत्रालय' मिला था (जबकि स्वतंत्र भारत के 1947 मंत्रिमंडल में प्रथम वित्त मंत्री आर.के. षणमुगम चेट्टी थे)।"},
  {"q":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) — इसके संबंध में 'प्रमुख राजनीतिक घटनाएँ' कौन/क्या था?","options":["सूरत (1907 — अध्यक्ष रासबिहारी घोष, नरम व गरम दल में विभाजन); मुस्लिम लीग (30 दिसंबर 1906 ढाका — आगा खाँ, सलीमुल्लाह व मोहसिन-उल-मुल्क); होमरूल लीग (अप्रैल 1916 तिलक — बेलगाम/पुणे; सितंबर 1916 एनी बेसेंट — अडयार, मद्रास)","28 दिसंबर 1885 गोकुलदास तेजपाल संस्कृत कॉलेज, बंबई (72 प्रतिनिधि, ए.ओ. ह्यूम द्वारा पहल, वायसराय डफरिन); 1885 बंबई (व्योमेश चंद्र बनर्जी); 1886 कलकत्ता (दादाभाई नौरोजी); 1887 मद्रास (बदरुद्दीन तैयबजी — प्रथम मुस्लिम अध्यक्ष); 1888 इलाहाबाद (जॉर्ज यूल — प्रथम अंग्रेज अध्यक्ष)","1896 कलकत्ता (रहीमतुल्ला सयानी — पहली बार 'वंदे मातरम'); 1905 बनारस (गोखले — स्वदेशी समर्थन); 1906 कलकत्ता (नौरोजी — 'स्वराज' लक्ष्य); 1911 कलकत्ता (बिशन नारायण धर — 'जन गण मन'); 1916 लखनऊ (अंबिका चरण मजूमदार — नरम-गरम व कांग्रेस-लीग समझौता)","1935 एक्ट के तहत फरवरी 1937 चुनाव: कांग्रेस ने 11 में से 5-6 प्रांतों में पूर्ण बहुमत व कुल 8 प्रांतों (बॉम्बे, मद्रास, उ.प्र., बिहार, म.प्र., उड़ीसा, NWFP, असम) में सरकार बनाई; अक्टूबर-नवंबर 1939 में बिना भारतीय सहमति द्वितीय विश्व युद्ध में भारत को शामिल करने पर इस्तीफा ('मुक्ति दिवस' 22 दिसंबर 1939 लीग-अंबेडकर द्वारा)"],"correct":0,"explanation":"20 अगस्त 1917 के मोंटेग्यू घोषणा पत्र (ब्रिटिश भारत में क्रमिक उत्तरदायी शासन) के बाद एनी बेसेंट ने अपना होमरूल आंदोलन स्थगित कर दिया।"},
  {"q":"[UPSC Prelims पैटर्न — स्वतंत्रता संग्राम की पुस्तकें] निम्नलिखित युग्मों पर विचार कीजिए:\n1. द डिस्कवरी ऑफ इंडिया : विनायक दामोदर सावरकर\n2. द इंडियन वार ऑफ इंडिपेंडेंस 1857 : लाला लाजपत राय\n3. अनहैप्पी इंडिया (1928) : महात्मा गांधी (लंदन से दक्षिण अफ्रीका जहाज पर)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: द डिस्कवरी ऑफ इंडिया — पं. जवाहरलाल नेहरू)। युग्म 2 गलत (सही: द इंडियन वार ऑफ इंडिपेंडेंस 1857 — विनायक दामोदर सावरकर)। युग्म 3 गलत (सही: अनहैप्पी इंडिया (1928) — लाला लाजपत राय)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942)\n3. करो या मरो (Do or Die) : स्वामी दयानंद सरस्वती\n4. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : लाला लाजपत राय (साइमन कमीशन विरोध)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":0,"explanation":"केवल युग्म 1 सही है: जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया। (अन्य सही युग्म: स्वराज मेरा जन्मसिद्ध अधिकार है→बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916), करो या मरो (Do or Die)→महात्मा गांधी (ग्वालिया टैंक मैदान, 8 अगस्त 1942), वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग→स्वामी दयानंद सरस्वती)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. सरफरोशी की तमन्ना... : रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)\n2. मेरे शरीर पर पड़ी एक-एक लाठी... : लाला लाजपत राय\n3. स्वराज मेरा जन्मसिद्ध अधिकार है : श्यामलाल गुप्त 'पार्षद'\n4. आराम हराम है / Who lives if India dies : जवाहरलाल नेहरू","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: 'स्वराज मेरा जन्मसिद्ध अधिकार है' का सही संबंध 'बाल गंगाधर तिलक' से है (न कि 'श्यामलाल गुप्त 'पार्षद'' से)। तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. स्वराज मेरा जन्मसिद्ध अधिकार है : बाल गंगाधर तिलक\n2. मेरे शरीर पर पड़ी एक-एक लाठी... : लाला लाजपत राय\n3. सरफरोशी की तमन्ना... : श्यामलाल गुप्त 'पार्षद'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया।) युग्म 2 सही (30 अक्टूबर 1928 को लाहौर में स्कॉट-सॉन्डर्स के लाठीचार्ज में घायल 'पंजाब केसरी' ने यह कहा।) युग्म 3 गलत (सही: सरफरोशी की तमन्ना... — रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी))।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. चार्टर अधिनियम, 1853 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।) युग्म 2 सही (1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।) युग्म 3 गलत (सही: चार्टर अधिनियम, 1853 — केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1940 रामगढ़ अधिवेशन : मौलाना अबुल कलाम आजाद\n2. 1907 सूरत अधिवेशन : पं. जवाहरलाल नेहरू\n3. 1929 लाहौर अधिवेशन : पं. बिशन नारायण धर\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1940 के रामगढ़ अधिवेशन में मौलाना आजाद अध्यक्ष बने और विश्व युद्ध संकट के कारण 1940-46 तक लगातार अध्यक्ष रहे।) युग्म 2 गलत (सही: 1907 सूरत अधिवेशन — डॉ. रासबिहारी घोष)। युग्म 3 गलत (सही: 1929 लाहौर अधिवेशन — पं. जवाहरलाल नेहरू)।"},
  {"q":"बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन — इसके संबंध में 'घटनाक्रम व नेतृत्व' कौन/क्या था?","options":["नरम दल (1885-1905: दादाभाई, गोखले, मेहता, सुरेंद्रनाथ — संवैधानिक 3P: प्रार्थना, याचिका, विरोध; शहरी अभिजात्य आधार, ब्रिटिश न्याय में आस्था); गरम दल (1905-1918: लाल-बाल-पाल व अरबिंदो — निष्क्रिय प्रतिरोध, बहिष्कार, राष्ट्रीय शिक्षा, जन-आंदोलन व पूर्ण स्वराज लक्ष्य)","बंगभाषा प्रकाशिका सभा (1836), लैंडहोल्डर्स सोसाइटी (1838 द्वारकानाथ टैगोर — प्रथम राजनीतिक संगठन), ईस्ट इंडिया एसोसिएशन (1866 लंदन, दादाभाई नौरोजी), पूना सार्वजनिक सभा (1870 एम.जी. रानाडे व जी.वी. जोशी), इंडियन एसोसिएशन (1876 सुरेंद्रनाथ बनर्जी व आनंद मोहन बोस)","घोषणा: 19/20 जुलाई 1905; टाउन हॉल बैठक: 7 अगस्त 1905 (बहिष्कार प्रस्ताव); प्रभावी: 16 अक्टूबर 1905 ('शोक दिवस', राखी दिवस व अरंधन); तिलक (बंबई-पुणे), लाजपत राय व अजीत सिंह (पंजाब), चिदंबरम पिल्लै (मद्रास), सैय्यद हैदर रजा (दिल्ली)","28 दिसंबर 1885 गोकुलदास तेजपाल संस्कृत कॉलेज, बंबई (72 प्रतिनिधि, ए.ओ. ह्यूम द्वारा पहल, वायसराय डफरिन); 1885 बंबई (व्योमेश चंद्र बनर्जी); 1886 कलकत्ता (दादाभाई नौरोजी); 1887 मद्रास (बदरुद्दीन तैयबजी — प्रथम मुस्लिम अध्यक्ष); 1888 इलाहाबाद (जॉर्ज यूल — प्रथम अंग्रेज अध्यक्ष)"],"correct":2,"explanation":"1908 में तिलक को 6 वर्ष के लिए मांडले जेल भेजे जाने पर बंबई के कपड़ा मिल मजदूरों ने भारत की पहली बड़ी राजनीतिक हड़ताल की।"},
  {"q":"[PSC/CDS युग्म पहचान — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. चार्ल्स मेटकाफ (1835-36) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड डलहौजी (1848-56) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n3. लॉर्ड रिपन (1880-84) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n4. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी। (अन्य सही युग्म: चार्ल्स मेटकाफ (1835-36)→1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना, लॉर्ड डलहौजी (1848-56)→व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854), लॉर्ड रिपन (1880-84)→स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / Who lives if India dies : जवाहरलाल नेहरू\n2. इंकलाब जिंदाबाद : भगत सिंह (रचयिता: हसरत मोहानी)\n3. सरफरोशी की तमन्ना... : श्यामलाल गुप्त 'पार्षद'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने स्वतंत्रता संग्राम व राष्ट्र-निर्माण के दौरान ये प्रेरक नारे दिए।) युग्म 2 सही (मूलतः मौलाना हसरत मोहानी (1921) द्वारा रचित इस नारे को भगत सिंह व बटुकेश्वर दत्त ने 1929 में अमर किया।) युग्म 3 गलत (सही: सरफरोशी की तमन्ना... — रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारत शासन अधिनियम, 1935   |   1. मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\nB. चार्टर अधिनियम, 1813   |   2. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\nC. भारतीय परिषद अधिनियम, 1909   |   3. कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\nD. पिट्स इंडिया एक्ट, 1784   |   4. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण), चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष), भारतीय परिषद अधिनियम, 1909 (मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य), पिट्स इंडिया एक्ट, 1784 (कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण)।"},
  {"q":"बंगाल विभाजन (1905), भारतीय विश्वविद्यालय अधिनियम (1904) और 'प्राचीन स्मारक संरक्षण अधिनियम' किस वायसराय के प्रमुख कार्य थे?","options":["बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन","बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना","सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)","द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त"],"correct":0,"explanation":"लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी। गोपाल कृष्ण गोखले ने कर्जन के शासन की तुलना औरंगजेब के शासन से की।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारतीय परिषद अधिनियम, 1861   |   1. गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\nB. रेगुलेटिंग एक्ट, 1773   |   2. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nC. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   3. मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nD. चार्टर अधिनियम, 1833   |   4. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली","options":["A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":2,"explanation":"सही सुमेलन: भारतीय परिषद अधिनियम, 1861 (मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)), रेगुलेटिंग एक्ट, 1773 (गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ), भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"[UPSC Prelims PYQ] 1907 के 'सूरत कांग्रेस अधिवेशन' में नरमदल व गरमदल के बीच मुख्य विभाजन किन चार ऐतिहासिक प्रस्तावों के विवाद के इर्द-गिर्द केंद्रित था?","options":["नमक कर की तत्काल समाप्ति और दांडी मार्च की तिथि","1906 के कलकत्ता अधिवेशन में पारित 'स्वदेशी, बहिष्कार, राष्ट्रीय शिक्षा तथा स्वशासन (स्वराज)' के प्रस्तावों को कायम रखने व प्रसार करने का मुद्दा","प्रथम विश्व युद्ध में भारतीय सैनिक भेजने का विवाद","क्रिप्स मिशन के डोमिनियन स्टेटस प्रस्ताव को मानने या न मानने का विवाद"],"correct":1,"explanation":"गरमदल नेता 1906 में पारित स्वराज, स्वदेशी, बहिष्कार व राष्ट्रीय शिक्षा प्रस्तावों को पूरे भारत में फैलाना चाहते थे और तिलक/लाजपत राय को अध्यक्ष बनाना चाहते थे, जबकि रासबिहारी घोष अध्यक्ष बने।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\n2. लॉर्ड कॉर्नवालिस (1786-93) : बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\n3. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।) युग्म 2 सही (लॉर्ड कॉर्नवालिस को भारत में नागरिक सेवा (ICS) व संगठित पुलिस प्रणाली (थाना-दारोगा) का जनक माना जाता है।) युग्म 3 सही (अकाल के समय भव्य दिल्ली दरबार (1877) तथा भारतीय भाषाई समाचार-पत्रों पर सेंसरशिप लॉर्ड लिटन की देन थी।)।"},
  {"q":"'नरम दल बनाम गरम दल की विचारधारा एवं कार्यप्रणाली' के ऐतिहासिक संदर्भ में 'तिलक का योगदान' निम्नलिखित में से क्या है?","options":["'आमार सोनार बांग्ला' (टैगोर), 'बंगाल केमिकल्स' (पी.सी. राय), राष्ट्रीय शिक्षा परिषद (1906 सतीशचंद्र मुखर्जी व अरबिंदो घोष — बंगाल नेशनल कॉलेज); 1911 में दिल्ली दरबार में विभाजन रद्द","मद्रास महाजन सभा (1884 — वी. राघवाचारी, जी. सुब्रमण्यम अय्यर, पी. आनंद चारलु); बॉम्बे प्रेसीडेंसी एसोसिएशन (1885 — फिरोजशाह मेहता, के.टी. तैलंग, बदरुद्दीन तैयबजी)","सेफ्टी वॉल्व सिद्धांत (लाला लाजपत राय ने 'यंग इंडिया' में चर्चा की); आधुनिक मत: 'तड़ित चालक' (Lightning Conductor — गोखले ने ह्यूम का उपयोग किया)","गणपति उत्सव (1893) व शिवाजी उत्सव (1895) द्वारा जन-जागरण; अकाल के समय 1896 में पुणे में कर न देने का अभियान"],"correct":3,"explanation":"यद्यपि उदारवादियों को तात्कालिक सुधार कम मिले, किंतु उन्होंने दादाभाई नौरोजी व आर.सी. दत्त के नेतृत्व में ब्रिटिश साम्राज्यवाद की आर्थिक लूट को बेनकाब कर राष्ट्रवादी आधार तैयार किया।"},
  {"q":"ऐतिहासिक संदर्भ में 'घोषणा: 19/20 जुलाई 1905; टाउन हॉल बैठक: 7 अगस्त 1905 (बहिष्कार प्रस्ताव); प्रभावी: 16 अक्टूबर 1905 ('शोक दिवस', राखी दिवस व अरंधन); तिलक (बंबई-पुणे), लाजपत राय व अजीत सिंह (पंजाब), चिदंबरम पिल्लै (मद्रास), सैय्यद हैदर रजा (दिल्ली)' (घटनाक्रम व नेतृत्व) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन","कांग्रेस-पूर्व राजनीतिक संगठन (1836–1885)","भारतीय राष्ट्रीय कांग्रेस की स्थापना (1885) एवं प्रथम चार अधिवेशन","नरम दल बनाम गरम दल की विचारधारा एवं कार्यप्रणाली"],"correct":0,"explanation":"1908 में तिलक को 6 वर्ष के लिए मांडले जेल भेजे जाने पर बंबई के कपड़ा मिल मजदूरों ने भारत की पहली बड़ी राजनीतिक हड़ताल की।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं।\nकथन-2: 321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं। (2) 321 अनुच्छेद व 10 अनुसूचियों वाले 1935 के अधिनियम ने भारतीय संविधान के संरचनात्मक भाग में सर्वाधिक योगदान दिया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. आजाद हिंद फौज (INA) की पहली सैन्य स्थापना 1943 में बर्लिन में रासबिहारी बोस की बजाय सरदार भगत सिंह के नेतृत्व में हुई थी।\n2. प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'फ्लाउड आयोग (Floud Commission)' का ऐतिहासिक संबंध 'प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच' से था।\n3. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1924 बेलगाम अधिवेशन' का ऐतिहासिक संबंध 'सरोजिनी नायडू (प्रथम भारतीय महिला)' से था।\n4. अरबिंदो घोष ने 'न्यू लैम्प्स फॉर ओल्ड' लेखमाला व 'वंदे मातरम' पत्र के माध्यम से उदारवादियों की भिक्षावृत्ति की नीति की कड़ी आलोचना कर निष्क्रिय प्रतिरोध का सिद्धांत दिया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (अरबिंदो घोष ने 'न्यू लैम्प्स फॉर ओल्ड' लेखमाला व 'वंदे मातरम' पत्र के माध्यम से उदारवादियों की भिक्षावृत्ति की नीति की कड़ी आलोचना कर निष्क्रिय प्रतिरोध का सिद्धांत दिया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. विजयी विश्व तिरंगा प्यारा   B. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)\nC. स्वतंत्र भारत के प्रथम मंत्रिमंडल एवं संविधान निर्माण ऐतिहासिक तथ्य   D. अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","स्वतंत्र भारत के प्रथम मंत्रिमंडल एवं संविधान निर्माण ऐतिहासिक तथ्य","विजयी विश्व तिरंगा प्यारा"],"correct":1,"explanation":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), विजयी विश्व तिरंगा प्यारा (1924 ई.), अखिल भारतीय किसान सभा (1936), ट्रेड यूनियन (AITUC) व वामपंथ (1936 ई.), स्वतंत्र भारत के प्रथम मंत्रिमंडल एवं संविधान निर्माण ऐतिहासिक तथ्य (1947 ई.)। अतः सर्वप्रथम सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — क्रांतिकारी घटनाएँ एवं नायक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. मुजफ्फरपुर बम कांड (1908)   |   1. रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)\nB. दिल्ली षड्यंत्र केस (1912)   |   2. मदनलाल धींगरा\nC. बंगाल गवर्नर पर गोली (1932)   |   3. खुदीराम बोस एवं प्रफुल्ल चाकी\nD. कर्जन वायली वध (लंदन, 1909)   |   4. बीना दास","options":["A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: मुजफ्फरपुर बम कांड (1908) (खुदीराम बोस एवं प्रफुल्ल चाकी), दिल्ली षड्यंत्र केस (1912) (रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)), बंगाल गवर्नर पर गोली (1932) (बीना दास), कर्जन वायली वध (लंदन, 1909) (मदनलाल धींगरा)।"},
  {"q":"'बंगाल विभाजन (1905) एवं स्वदेशी व बहिष्कार आंदोलन' के ऐतिहासिक संदर्भ में 'रचनात्मक स्वदेशी' निम्नलिखित में से क्या है?","options":["सेफ्टी वॉल्व सिद्धांत (लाला लाजपत राय ने 'यंग इंडिया' में चर्चा की); आधुनिक मत: 'तड़ित चालक' (Lightning Conductor — गोखले ने ह्यूम का उपयोग किया)","'आमार सोनार बांग्ला' (टैगोर), 'बंगाल केमिकल्स' (पी.सी. राय), राष्ट्रीय शिक्षा परिषद (1906 सतीशचंद्र मुखर्जी व अरबिंदो घोष — बंगाल नेशनल कॉलेज); 1911 में दिल्ली दरबार में विभाजन रद्द","गणपति उत्सव (1893) व शिवाजी उत्सव (1895) द्वारा जन-जागरण; अकाल के समय 1896 में पुणे में कर न देने का अभियान","मद्रास महाजन सभा (1884 — वी. राघवाचारी, जी. सुब्रमण्यम अय्यर, पी. आनंद चारलु); बॉम्बे प्रेसीडेंसी एसोसिएशन (1885 — फिरोजशाह मेहता, के.टी. तैलंग, बदरुद्दीन तैयबजी)"],"correct":1,"explanation":"1908 में तिलक को 6 वर्ष के लिए मांडले जेल भेजे जाने पर बंबई के कपड़ा मिल मजदूरों ने भारत की पहली बड़ी राजनीतिक हड़ताल की।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)   B. लॉर्ड कर्जन (1899-1905)\nC. भारत शासन अधिनियम 1919 (मोंटेग्यू-चेम्सफोर्ड) व 1935 का अधिनियम   D. इंकलाब जिंदाबाद\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932)","इंकलाब जिंदाबाद","लॉर्ड कर्जन (1899-1905)","भारत शासन अधिनियम 1919 (मोंटेग्यू-चेम्सफोर्ड) व 1935 का अधिनियम"],"correct":2,"explanation":"लॉर्ड कर्जन (1899-1905) (1905 ई.), इंकलाब जिंदाबाद (1929 ई.), गांधी-इरविन समझौता (1931), गोलमेज सम्मेलन व पूना पैक्ट (1932) (1932 ई.), भारत शासन अधिनियम 1919 (मोंटेग्यू-चेम्सफोर्ड) व 1935 का अधिनियम (1935 ई.)। अतः सर्वप्रथम लॉर्ड कर्जन (1899-1905)।"},
  {"q":"[PSC/CDS युग्म पहचान — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. 1896 कलकत्ता अधिवेशन : पं. जवाहरलाल नेहरू\n2. 1929 लाहौर अधिवेशन : अंबिका चरण मजूमदार\n3. 1907 सूरत अधिवेशन : डॉ. रासबिहारी घोष\n4. 1916 लखनऊ अधिवेशन : व्योमेश चंद्र बनर्जी","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए। (अन्य सही युग्म: 1896 कलकत्ता अधिवेशन→रहीमतुल्ला एम. सयानी, 1929 लाहौर अधिवेशन→पं. जवाहरलाल नेहरू, 1916 लखनऊ अधिवेशन→अंबिका चरण मजूमदार)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. आराम हराम है / 'Who lives if India dies?'   B. द डिस्कवरी ऑफ इंडिया\nC. लॉर्ड कर्जन (1899-1905)   D. 1924 बेलगाम अधिवेशन\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["1924 बेलगाम अधिवेशन","द डिस्कवरी ऑफ इंडिया","आराम हराम है / 'Who lives if India dies?'","लॉर्ड कर्जन (1899-1905)"],"correct":3,"explanation":"लॉर्ड कर्जन (1899-1905) (1905 ई.), 1924 बेलगाम अधिवेशन (1924 ई.), आराम हराम है / 'Who lives if India dies?' (1929 ई.), द डिस्कवरी ऑफ इंडिया (1946 ई.)। अतः सर्वप्रथम लॉर्ड कर्जन (1899-1905)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: ऐतिहासिक नारे एवं उद्घोष के अंतर्गत 'स्वराज मेरा जन्मसिद्ध अधिकार है' का ऐतिहासिक संबंध 'लाला लाजपत राय' से था।\nकथन-2: गवर्नर-जनरल / वायसराय एवं कार्य के अंतर्गत 'लॉर्ड रिपन (1880-84)' का ऐतिहासिक संबंध 'बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'स्वराज मेरा जन्मसिद्ध अधिकार है' का सही संबंध 'बाल गंगाधर तिलक' से था — तिलक ने 1916 के लखनऊ अधिवेशन में होमरूल आंदोलन के दौरान यह अमर उद्घोष किया। (2) 'लॉर्ड रिपन (1880-84)' का सही संबंध 'स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग' से था — फ्लोरेंस नाइटिंगेल ने लॉर्ड रिपन को 'भारत का उद्धारक' कहा था।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. ली आयोग (Lee Commission, 1923)   B. सरफरोशी की तमन्ना...\nC. 1916 लखनऊ अधिवेशन   D. ब्रिटिश साम्राज्य के ताबूत में कील\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["ब्रिटिश साम्राज्य के ताबूत में कील","सरफरोशी की तमन्ना...","1916 लखनऊ अधिवेशन","ली आयोग (Lee Commission, 1923)"],"correct":0,"explanation":"1916 लखनऊ अधिवेशन (1916 ई.), ली आयोग (Lee Commission, 1923) (1923 ई.), सरफरोशी की तमन्ना... (1927 ई.), ब्रिटिश साम्राज्य के ताबूत में कील (1928 ई.)। अतः सबसे अंत में ब्रिटिश साम्राज्य के ताबूत में कील।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. 1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र)   B. करो या मरो (Do or Die)\nC. स्वराजियों की विधायी उपलब्धियाँ व बटलर समिति / बारदोली (1927-28)   D. 1917 कलकत्ता अधिवेशन\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["स्वराजियों की विधायी उपलब्धियाँ व बटलर समिति / बारदोली (1927-28)","1917 कलकत्ता अधिवेशन","करो या मरो (Do or Die)","1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र)"],"correct":1,"explanation":"1917 कलकत्ता अधिवेशन (1917 ई.), स्वराजियों की विधायी उपलब्धियाँ व बटलर समिति / बारदोली (1927-28) (1925 ई.), 1937 फैजपुर अधिवेशन (प्रथम ग्रामीण सत्र) (1937 ई.), करो या मरो (Do or Die) (1942 ई.)। अतः सर्वप्रथम 1917 कलकत्ता अधिवेशन।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. हैदराबाद रियासत का भारत में विलय सितंबर 1948 में जनमत संग्रह (Referendum) द्वारा जबकि जूनागढ़ का विलय 'ऑपरेशन पोलो' सैन्य कार्रवाई द्वारा हुआ।\n2. 1946 की अंतरिम सरकार में मुस्लिम लीग के सदस्य लियाकत अली खाँ को रक्षा मंत्रालय तथा बलदेव सिंह को वित्त मंत्रालय सौंपा गया था।\n3. क्रांतिकारी घटनाएँ एवं नायक के अंतर्गत 'मुजफ्फरपुर बम कांड (1908)' का ऐतिहासिक संबंध 'मदनलाल धींगरा' से था।\n4. तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (तिलक की होमरूल लीग (महाराष्ट्र-बंबई छोड़कर, मध्य प्रांत व बरार, 6 शाखाएँ) स्वराज व भाषाई राज्यों पर केंद्रित थी, जबकि एनी बेसेंट की अखिल भारतीय लीग की लगभग 200 शाखाएँ थीं (जॉर्ज अरुंडेल संगठन सचिव)।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1917 कलकत्ता अधिवेशन   |   1. आचार्य जे.बी. कृपलानी\nB. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   2. व्योमेश चंद्र बनर्जी\nC. 1925 कानपुर अधिवेशन   |   3. डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\nD. 1885 बंबई अधिवेशन (प्रथम)   |   4. सरोजिनी नायडू (प्रथम भारतीय महिला)","options":["A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2"],"correct":0,"explanation":"सही सुमेलन: 1917 कलकत्ता अधिवेशन (डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1925 कानपुर अधिवेशन (सरोजिनी नायडू (प्रथम भारतीय महिला)), 1885 बंबई अधिवेशन (प्रथम) (व्योमेश चंद्र बनर्जी)।"},
  {"q":"[UPSC Prelims PYQ] 1905 के स्वदेशी आंदोलन के संदर्भ में कौन-से नवाचार भारतीय स्वतंत्रता संग्राम में पहली बार व्यापक रूप से दिखे?","options":["सुभाषचंद्र बोस द्वारा सिंगापुर में आजाद हिंद बैंक की स्थापना","ब्रिटिश वस्तुओं का बहिष्कार, स्वदेशी उद्यम (बंगाल केमिकल्स, चिदंबरम पिल्लई का स्वदेशी स्टीम नेविगेशन), राष्ट्रीय शिक्षा परिषद एवं आत्मनिर्भरता ('आत्मशक्ति')","गांधीजी द्वारा व्यक्तिगत सत्याग्रह का राष्ट्रव्यापी संचालन","भारतीय राष्ट्रीय कांग्रेस द्वारा पूर्ण स्वाधीनता एवं संविधान सभा प्रस्ताव पारित करना"],"correct":1,"explanation":"स्वदेशी आंदोलन (1905-08) में प्रफुल्लचंद्र राय, रवींद्रनाथ ठाकुर, वी.ओ. चिदंबरम पिल्लई और सतीश चंद्र मुखर्जी (डॉन सोसाइटी) ने रचनात्मक स्वदेशी व राष्ट्रीय शिक्षा को सशक्त बनाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।\nकथन-2: 1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए। (2) 1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड लिटन (1876-80)   |   1. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nB. लॉर्ड लिनलिथगो (1936-44)   |   2. 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\nC. चार्ल्स मेटकाफ (1835-36)   |   3. वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\nD. लॉर्ड कॉर्नवालिस (1786-93)   |   4. प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":0,"explanation":"सही सुमेलन: लॉर्ड लिटन (1876-80) (वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट), लॉर्ड लिनलिथगो (1936-44) (प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन), चार्ल्स मेटकाफ (1835-36) (1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)   B. स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)\nC. इंकलाब जिंदाबाद   D. राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन","स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928)","सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)","इंकलाब जिंदाबाद"],"correct":2,"explanation":"सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916) (1917 ई.), स्वराज पार्टी (1923), साइमन कमीशन (1927) व नेहरू रिपोर्ट (1928) (1923 ई.), इंकलाब जिंदाबाद (1929 ई.), राजगोपालाचारी फार्मूला (1944), देसाई-लियाकत व वेवेल शिमला सम्मेलन (1945 ई.)। अतः सर्वप्रथम सूरत फूट (1907), मुस्लिम लीग (1906) व होमरूल लीग (1916)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. 1925 कानपुर अधिवेशन : सरोजिनी नायडू (प्रथम भारतीय महिला)\n2. 1896 कलकत्ता अधिवेशन : रहीमतुल्ला एम. सयानी\n3. 1917 कलकत्ता अधिवेशन : सरदार वल्लभभाई पटेल\n4. 1887 मद्रास अधिवेशन : बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":2,"explanation":"युग्म 3 गलत है: '1917 कलकत्ता अधिवेशन' का सही संबंध 'डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)' से है (न कि 'सरदार वल्लभभाई पटेल' से)। एनी बेसेंट 1917 कलकत्ता अधिवेशन में भारतीय राष्ट्रीय कांग्रेस की पहली महिला अध्यक्ष बनीं।"},
  {"q":"[UPSC Prelims पैटर्न — कांग्रेस अधिवेशन एवं अध्यक्ष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. 1907 सूरत अधिवेशन : डॉ. रासबिहारी घोष\n2. 1925 कानपुर अधिवेशन : सरोजिनी नायडू (प्रथम भारतीय महिला)\n3. 1911 कलकत्ता अधिवेशन : पं. बिशन नारायण धर\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सूरत (ताप्ती तट) में गरम दल व नरम दल के विवाद में रासबिहारी घोष अध्यक्ष चुने गए।) युग्म 2 सही (भारत कोकिला सरोजिनी नायडू 1925 कानपुर अधिवेशन की अध्यक्ष चुनी गईं।) युग्म 3 सही (27 दिसंबर 1911 को कलकत्ता अधिवेशन में बिशन नारायण धर की अध्यक्षता में पहली बार जन गण मन गाया गया।)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. लॉर्ड लिटन (1876-80) : वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\n2. लॉर्ड कर्जन (1899-1905) : 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण\n3. लॉर्ड रिपन (1880-84) : स्थानीय स्वशासन प्रस्ताव (1882), वर्नाक्युलर प्रेस एक्ट की समाप्ति व हंटर शिक्षा आयोग\n4. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'लॉर्ड कर्जन (1899-1905)' का सही संबंध 'बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन' से है (न कि '1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण' से)। लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. प्रमुख आयोग एवं उद्देश्य के अंतर्गत 'बटलर समिति (1927 ई.)' का ऐतिहासिक संबंध 'जलियाँवाला बाग व पंजाब उपद्रवों की जांच (चमनलाल सीतलवाड़ व सुल्तान अहमद भारतीय सदस्य)' से था।\n2. कांग्रेस अधिवेशन एवं अध्यक्ष के अंतर्गत '1925 कानपुर अधिवेशन' का ऐतिहासिक संबंध 'पं. जवाहरलाल नेहरू' से था।\n3. संवैधानिक अधिनियम एवं प्रावधान के अंतर्गत 'भारत शासन अधिनियम, 1858' का ऐतिहासिक संबंध 'मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)' से था।\n4. 16 अक्टूबर 1905 को बंगाल विभाजन लागू होने पर रवींद्रनाथ टैगोर के आह्वान पर हिंदू-मुसलमानों ने एक-दूसरे को 'राखी' बाँधकर एकता प्रदर्शित की और कृष्ण कुमार मित्र के 'संजीवनी' पत्र ने सर्वप्रथम बहिष्कार का सुझाव दिया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (16 अक्टूबर 1905 को बंगाल विभाजन लागू होने पर रवींद्रनाथ टैगोर के आह्वान पर हिंदू-मुसलमानों ने एक-दूसरे को 'राखी' बाँधकर एकता प्रदर्शित की और कृष्ण कुमार मित्र के 'संजीवनी' पत्र ने सर्वप्रथम बहिष्कार का सुझाव दिया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"}
]);
